Method.Source:
/// <summary>
/// get image with company change
/// </summary>
/// <param name = "_imageName">SysDocuBrandImageRef</param>
/// <param name = "_companyId">CompanyId</param>
/// <returns>container</returns>
static container avaGetImage(SysDocuBrandImageRef _imageName, CompanyId _companyId = curExt())
{
    container avaGetImage;

    changecompany(_companyId)
    {
        avaGetImage = SysDocuBrandImages::getImage(_imageName);
    }

    return avaGetImage;
}
